.py-24{padding-top: 6rem; padding-bottom: 6rem;}
.py-3\.5{padding-top: 0.875rem; padding-bottom: 0.875rem;}
.text-center{text-align: center;}
.font-sans{font-family: "Plus Jakarta Sans", sans-serif;}
.font-serif{font-family: Cinzel, serif;}
.text-xs{font-size: 0.75rem; line-height: 1rem;}
.text-sm{font-size: 0.875rem; line-height: 1.25rem;}
.text-4xl{font-size: 2.25rem; line-height: 2.5rem;}
.font-bold{font-weight: 700;}
.font-light{font-weight: 300;}
.font-normal{font-weight: 400;}
.uppercase{text-transform: uppercase;}
.leading-relaxed{line-height: 1.625;}
.leading-tight{line-height: 1.25;}
.tracking-\[0\.4em\]{letter-spacing: 0.4em;}
.tracking-tight{letter-spacing: -0.025em;}
.tracking-widest{letter-spacing: 0.1em;}
.text-cyan-400{--tw-text-opacity: 1; color: rgb(34 211 238 / var(--tw-text-opacity, 1));}
.text-slate-400{--tw-text-opacity: 1; color: rgb(148 163 184 / var(--tw-text-opacity, 1));}
.text-slate-950{--tw-text-opacity: 1; color: rgb(2 6 23 / var(--tw-text-opacity, 1));}
.text-white{--tw-text-opacity: 1; color: rgb(255 255 255 / var(--tw-text-opacity, 1));}
.placeholder-slate-600::placeholder{--tw-placeholder-opacity: 1; color: rgb(71 85 105 / var(--tw-placeholder-opacity, 1));}
.blur-\[120px\]{--tw-blur: blur(120px); filter: var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow);}
.transition-colors{transition-property: color, background-color, border-color, text-decoration-color, fill, stroke, -webkit-text-decoration-color; transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1); transition-duration: 150ms;}
.duration-300{transition-duration: 300ms;}
.hover\:bg-cyan-400:hover{--tw-bg-opacity: 1; background-color: rgb(34 211 238 / var(--tw-bg-opacity, 1));}
.focus\:border-cyan-500:focus{--tw-border-opacity: 1; border-color: rgb(6 182 212 / var(--tw-border-opacity, 1));}
.focus\:outline-none:focus{outline: transparent solid 2px; outline-offset: 2px;}
@media (min-width: 640px){.sm\:flex-row{flex-direction: row;}}
@media (min-width: 640px){.sm\:text-left{text-align: left;}}
@media (min-width: 768px){.md\:p-24{padding: 6rem;}}
@media (min-width: 768px){.md\:text-6xl{font-size: 3.75rem; line-height: 1;}}
@media (min-width: 768px){.md\:text-base{font-size: 1rem; line-height: 1.5rem;}}
@media (min-width: 1024px){.lg\:px-16{padding-left: 4rem; padding-right: 4rem;}}
